  const observer=new MutationObserver(changes=>{for(const c of changes)for(const n of c.addedNodes)visit(n);});observer.observe(document.body,{subtree:true,childList:true});w.__m03ControlRows=rows;w.__m03ControlObserver=observer;
});}
